/**
 * TrailStep MCP server.
 *
 * Uses the low-level `Server` from @modelcontextprotocol/sdk with explicit
 * `setRequestHandler` registrations (no zod, no high-level `McpServer`).
 * The `tools` registry below wires every generic MCP tool (`trst_run_workflow`,
 * `trst_watch`, `trst_answer`, `trst_resume`) with a plain JSON Schema
 * `inputSchema`; CallTool dispatches to the real tool implementations in
 * `tools/` and reports failures as `isError` tool results.
 *
 * Per-workflow tools (`.trailstep/mcp/trst_<id>.json`, regenerated by
 * `trailstep add` / `trailstep update`) are layered on top of the generic
 * registry: with the default `mcp.perWorkflowTools: true` each generated JSON
 * is listed as its own `trst_<id>` tool (params from the JSON `inputSchema`)
 * and dispatches to `runWorkflowTool` with the JSON's `workflowRef` preset;
 * with `mcp.perWorkflowTools: false` the server lists a single `trst_list`
 * discovery tool instead. The tool JSONs and config are re-read fresh on every
 * ListTools/CallTool request (no regeneration logic in the server).
 *
 * Resources: `trailstep://project` (resolved project directory as JSON) and
 * `trailstep://instructions` (generic + static snippet markdown; the project's
 * `.trailstep/mcp/instructions.md` is served when present).
 */
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListResourcesRequestSchema,
  ListToolsRequestSchema,
  ReadResourceRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";
import {
  loadPerWorkflowTools,
  type PerWorkflowToolDefinition,
  resolvePerWorkflowToolsEnabled,
} from "./tools/per_workflow.js";
import { runWorkflowTool } from "./tools/run_workflow.js";
import { trstAnswer } from "./tools/trst_answer.js";
import { trstList } from "./tools/trst_list.js";
import { trstResume } from "./tools/trst_resume.js";
import { type TrstWatchProgressEvent, trst_watch } from "./tools/trst_watch.js";

export interface McpToolDefinition {
  readonly name: string;
  readonly description: string;
  readonly inputSchema: {
    readonly type: "object";
    readonly properties: Record<string, unknown>;
    readonly required?: readonly string[];
    readonly additionalProperties?: boolean;
  };
}

const projectDirProperty = {
  type: "string",
  description:
    "Optional project directory for run resolution. Defaults to the server project directory.",
} as const;

/** Tool registry: every MCP tool with its plain JSON Schema input contract. */
export const tools: readonly McpToolDefinition[] = [
  {
    name: "trst_run_workflow",
    description:
      'Start a TrailStep workflow run in the background and return immediately with {runId, runDir, status, workflow}. status is "started" only once the background run\'s directory actually materializes (bounded verification); when the run never starts (missing or refused CLI entry, spawn failure, or a run directory that never appears), status is "failed" with an "error" field and the result is reported as an isError tool result — never a false "started". When a per-workflow tool exists for the workflow you want (for example trst_delegate or trst_take-it-away), prefer it: it already knows the workflow reference and its input schema. Use this generic tool only when no per-workflow tool covers the workflow. Follow it with trst_watch, which blocks until the run finishes or needs an answer.',
    inputSchema: {
      type: "object",
      properties: {
        workflow: {
          type: "string",
          description: "Workflow reference (package id, bundle id, or workflow file path).",
        },
        input: {
          type: "object",
          additionalProperties: true,
          description: "Workflow input; must be a plain JSON object when provided.",
        },
        project: projectDirProperty,
      },
      required: ["workflow"],
    },
  },
  {
    name: "trst_watch",
    description:
      "Blocking wait-for-attention call on a TrailStep run: it returns as soon as the run finishes or needs you, instead of tailing events. Use it after trst_run_workflow (or a per-workflow tool) and after trst_resume. Required: runId. Optional: cursor (byte offset, overrides the persisted per-run cursor), maxWaitMs (default 300000 = 5 min, 0 = single-shot), waitFor (attention default | terminal), verbosity (brief / normal default / full raw-event escape hatch). Read state and act: started (no events yet) — call again; in-progress (a live process holds the run) — call again with the same params; waiting (the run is parked on durable waits) — answer every waits[] entry with trst_answer (branchId disambiguates parallel branches), continue with trst_resume, then call again; terminal — read output, or failure with code/message/details, then stop; crashed — no terminal event and no live process holds the run, so nothing will ever append: stop. One call covers up to maxWaitMs: do not poll in a loop and do not sleep between calls. Capability degradation: with a progress token the server keeps the request alive and the call may block the full budget; without one it caps at 25 s, sends no progress notifications, and returns an in-progress snapshot when the budget expires so you can call again — effectiveWaitMs reports which budget was used. The compact result carries output, waits[], failure, crash or progress; verbosity full adds raw JSONL lines.",
    inputSchema: {
      type: "object",
      properties: {
        runId: {
          type: "string",
          description: "Run name or run id to observe.",
        },
        cursor: {
          type: "number",
          description:
            "Byte offset into events.jsonl to resume from; overrides the persisted cursor.",
        },
        verbosity: {
          type: "string",
          enum: ["brief", "normal", "full"],
          description:
            "Output detail: brief 50 / normal 100 / full 200 line cap. Raw lines are only populated for full (the raw-event escape hatch); brief and normal return the compact result.",
        },
        maxWaitMs: {
          type: "number",
          description:
            "Requested blocking budget in ms. Defaults to 300000 (5 minutes; the ceiling). 0 returns an immediate single-shot snapshot. Without a client progress token the effective budget is capped at 25 s; if the budget expires the call returns an in-progress snapshot to call again. effectiveWaitMs reports the budget actually used.",
        },
        waitFor: {
          type: "string",
          enum: ["attention", "terminal"],
          description:
            '"attention" (default) returns as soon as the run is waiting, terminal or crashed. "terminal" ignores pending waits and blocks until the run settles or the budget expires; use it only when you care about finishing, not about answering.',
        },
        project: projectDirProperty,
      },
      required: ["runId"],
    },
  },
  {
    name: "trst_answer",
    description:
      "Answer a pending TrailStep wait by persisting the answer into the run's real wait answer file (optionally continuing the run). Required: runId and waitId identify the pending wait; answer must be a plain JSON object persisted verbatim as the recommendation. Optional: branchId disambiguates same-id waits pending on parallel branches; continueAfterAnswer runs the same continue path trst_resume uses after persisting.",
    inputSchema: {
      type: "object",
      properties: {
        runId: {
          type: "string",
          description: "Run name (under the runs root) or run directory path.",
        },
        waitId: {
          type: "string",
          description: "Id of the pending wait to answer.",
        },
        answer: {
          type: "object",
          additionalProperties: true,
          description: "Answer payload persisted verbatim into the wait answer file (JSON object).",
        },
        branchId: {
          type: "string",
          description: "Disambiguates same-id waits pending on parallel branches.",
        },
        continueAfterAnswer: {
          type: "boolean",
          description: "After persisting the answer, run the same continue path trst_resume uses.",
        },
        project: projectDirProperty,
      },
      required: ["runId", "waitId", "answer"],
    },
  },
  {
    name: "trst_resume",
    description:
      "Start (or continue) a run's `continue` in the background and return as soon as it has begun. Does not wait for the run to finish — follow it with `trst_watch`, which blocks until the run finishes or needs an answer. Required: runId. The result reports the continue status (completed / waiting / cancelled / failed / running) derived from the run's event trail, background: true while the continue is still executing, and an error when the continue did not start.",
    inputSchema: {
      type: "object",
      properties: {
        runId: {
          type: "string",
          description: "Run name (under the runs root) or run directory path.",
        },
        project: projectDirProperty,
      },
      required: ["runId"],
    },
  },
];

export interface CreateServerOptions {
  /** Project directory the server operates against (already absolute). */
  readonly projectDir?: string;
  /**
   * Home directory anchoring the global config/tool JSON layers. Defaults to
   * the real home directory; tests inject a tmp dir for isolation.
   */
  readonly homeDir?: string;
  /**
   * Test seam: cadence for per-poll `notifications/progress` messages. Defaults
   * to the trst_watch cadence (10 s).
   */
  readonly progressIntervalMs?: number;
}

/**
 * The slice of the SDK's `RequestHandlerExtra` the CallTool handler uses. The
 * structural shape keeps the dispatch layer independent of the SDK's generic
 * request/notification unions.
 */
interface CallToolExtra {
  readonly signal: AbortSignal;
  readonly _meta?: { readonly progressToken?: string | number };
  readonly sendNotification: (notification: {
    readonly method: "notifications/progress";
    readonly params: {
      readonly progressToken: string | number;
      readonly progress: number;
      readonly total?: number;
      readonly message?: string;
    };
  }) => Promise<void>;
}

const SERVER_INFO = { name: "trailstep-mcp", version: "0.1.0" } as const;

/**
 * Server instructions sent on initialize: the run -> watch -> answer -> resume
 * loop, with a pointer to the `trailstep://instructions` resource that carries
 * the same mapping in detail.
 */
export const SERVER_INSTRUCTIONS =
  "TrailStep workflow runs use a run -> watch -> answer -> resume loop: start a run with trst_run_workflow (or a per-workflow trst_* tool), then call trst_watch (required runId). trst_watch is a blocking wait-for-attention call, not a poll loop: it returns started (call again), in-progress (call again with the same params), waiting (answer every waits[] entry with trst_answer — branchId disambiguates parallel branches — then trst_resume and call trst_watch again), terminal (read output or failure and stop), or crashed (no terminal event and no live process; stop). One call covers up to maxWaitMs (default 5 minutes); do not poll in a loop or sleep between calls. Clients that send a progress token keep the request alive for the full budget; clients without one are capped at 25 s and call again. The trailstep://instructions resource describes this loop in detail.";

export const PROJECT_RESOURCE_URI = "trailstep://project";
export const INSTRUCTIONS_RESOURCE_URI = "trailstep://instructions";

/**
 * `trst_list` tool definition (list mode only):
 * `mcp.perWorkflowTools: false` lists this instead of the per-workflow tools.
 */
export const TRST_LIST_TOOL: McpToolDefinition = {
  name: "trst_list",
  description:
    "List the available per-workflow TrailStep tools ({name, description}) from the generated .trailstep/mcp tool JSONs.",
  inputSchema: {
    type: "object",
    properties: {},
  },
};

/** Names owned by the generic registry; per-workflow JSONs cannot shadow them. */
const RESERVED_TOOL_NAMES = new Set<string>([
  ...tools.map((tool) => tool.name),
  TRST_LIST_TOOL.name,
]);

/**
 * Tools exposed on ListTools for the current mode: generic registry plus
 * either the per-workflow tools (default) or `trst_list` (list mode). Tool
 * JSONs and the mode flag are read fresh per call.
 */
export function listedToolDefinitions(
  projectDir: string,
  homeDir?: string,
): readonly McpToolDefinition[] {
  const options = {
    projectDir,
    ...(homeDir === undefined ? {} : { homeDir }),
  };
  const perWorkflowTools = loadPerWorkflowTools(options).filter(
    (tool) => !RESERVED_TOOL_NAMES.has(tool.name),
  );
  if (resolvePerWorkflowToolsEnabled(options)) {
    return [...tools, ...perWorkflowTools];
  }
  return [...tools, TRST_LIST_TOOL];
}

/**
 * Fallback instructions content: generic usage guidance plus the static
 * tool-mapping snippet (mirrors `.trailstep/mcp/instructions.md`).
 */
export const INSTRUCTIONS_FALLBACK = `# TrailStep MCP Instructions

## Embedded generic snippet

Actionable guidance for the generic TrailStep MCP toolkit (\`trst_run_workflow\`, \`trst_watch\`, \`trst_answer\`, \`trst_resume\`, and \`trst_list\`):

- Start a run with \`trst_run_workflow\` (or the per-workflow \`trst_<id>\` tool for a workflow that has one; \`trst_list\` lists the available per-workflow tools).
- Follow it with \`trst_watch\`, a blocking wait-for-attention call rather than a poll loop. Required \`runId\`; optional \`cursor\` (byte offset, overrides the persisted cursor), \`maxWaitMs\` (default 300000 = 5 min; 0 = single-shot), \`waitFor\` (\`attention\` default | \`terminal\`), and \`verbosity\` (\`brief\` / \`normal\` default / \`full\` raw-event escape hatch). One call covers up to the budget: call it again only after it returns, never in a loop or with a sleep.
  - \`started\` (no events yet) or \`in-progress\` (a live process holds the run): call again with the same params.
  - \`waiting\`: answer every \`waits[]\` entry with \`trst_answer\` (\`branchId\` disambiguates parallel branches), then \`trst_resume\`, then \`trst_watch\` again.
  - \`terminal\`: read \`output\`, or \`failure\` (code, message, optional details), and stop.
  - \`crashed\`: no terminal event and no live process holds the run, so nothing will ever append one — stop.
- Answer a pending wait with \`trst_answer\`: required \`runId\` + \`waitId\` + \`answer\` (plain JSON object); optional \`branchId\` and \`continueAfterAnswer\`.
- Resume a waiting run with \`trst_resume\`: required \`runId\`; starts the continue in the background and returns once it has begun — follow it with \`trst_watch\`, which blocks until the run finishes or needs an answer.
- Clients that send a progress token keep the watch request alive and may block the full \`maxWaitMs\` (default 5 minutes). Clients without one are capped at 25 s, receive no progress notifications, and, when the budget expires, get an in-progress snapshot to call again; \`effectiveWaitMs\` reports which budget was used.

## Embedded static snippet

\`\`\`json
{
  "watch": "trst_watch",
  "answer": "trst_answer",
  "resume": "trst_resume"
}
\`\`\`
`;

/** Build the low-level MCP server with ListTools/CallTool/ListResources/ReadResource handlers. */
export function createServer(options: CreateServerOptions = {}): Server {
  const projectDir = options.projectDir ?? path.resolve(".");
  const homeDir = options.homeDir;

  const server = new Server(SERVER_INFO, {
    capabilities: {
      tools: {},
      resources: {},
    },
    instructions: SERVER_INSTRUCTIONS,
  });

  server.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: listedToolDefinitions(projectDir, homeDir).map((tool) => ({
      name: tool.name,
      description: tool.description,
      inputSchema: {
        type: "object" as const,
        properties: tool.inputSchema.properties,
        ...(tool.inputSchema.required ? { required: [...tool.inputSchema.required] } : {}),
        ...(tool.inputSchema.additionalProperties === undefined
          ? {}
          : { additionalProperties: tool.inputSchema.additionalProperties }),
      },
    })),
  }));

  server.setRequestHandler(CallToolRequestSchema, async (request, extra) => {
    const name = request.params.name;
    const args = (request.params.arguments ?? {}) as Record<string, unknown>;
    try {
      const result = await dispatchTool(
        name,
        args,
        projectDir,
        homeDir,
        extra,
        options.progressIntervalMs,
      );
      return {
        content: [{ type: "text" as const, text: JSON.stringify(result) }],
      };
    } catch (error) {
      if (error instanceof ToolReportError) {
        // Structured failure payload (e.g. run_workflow status "failed", an
        // unanswered wait, or a failed continue): an isError result whose text
        // is the JSON payload, so callers can parse the failure fields while
        // still seeing the failure.
        return {
          content: [{ type: "text" as const, text: JSON.stringify(error.payload) }],
          isError: true,
        };
      }
      return toolError(`${name}: ${error instanceof Error ? error.message : String(error)}`);
    }
  });

  server.setRequestHandler(ListResourcesRequestSchema, async () => ({
    resources: [
      {
        uri: PROJECT_RESOURCE_URI,
        name: "TrailStep project",
        description: "The project directory this MCP server operates against.",
        mimeType: "application/json",
      },
      {
        uri: INSTRUCTIONS_RESOURCE_URI,
        name: "TrailStep MCP instructions",
        description: "Generic usage instructions plus the static tool-mapping snippet.",
        mimeType: "text/markdown",
      },
    ],
  }));

  server.setRequestHandler(ReadResourceRequestSchema, async (request) => {
    const uri = request.params.uri;
    if (uri === PROJECT_RESOURCE_URI) {
      return {
        contents: [
          {
            uri,
            mimeType: "application/json",
            text: JSON.stringify({ projectDir }),
          },
        ],
      };
    }
    if (uri === INSTRUCTIONS_RESOURCE_URI) {
      return {
        contents: [
          {
            uri,
            mimeType: "text/markdown",
            text: readInstructions(projectDir),
          },
        ],
      };
    }
    throw new Error(`Unknown resource: ${uri}`);
  });

  return server;
}

/** Connect the server over stdio (foreground; caller owns the process lifetime). */
export async function serveStdio(options: CreateServerOptions = {}): Promise<Server> {
  const server = createServer(options);
  await server.connect(new StdioServerTransport());
  return server;
}

/**
 * Dispatch completed but the tool reported an operational failure with a
 * structured JSON payload (run_workflow `status: "failed"`). Rethrown through
 * dispatch so the CallTool handler can emit an `isError` tool result whose
 * text is the payload — consistent with the server's convention that failures
 * are `isError` results and a started run is plain content.
 */
class ToolReportError extends Error {
  readonly payload: unknown;

  constructor(payload: unknown) {
    super("tool reported a failed result");
    this.payload = payload;
  }
}

function toolError(text: string): {
  content: { type: "text"; text: string }[];
  isError: true;
} {
  return {
    content: [{ type: "text" as const, text }],
    isError: true,
  };
}

/**
 * Dispatch a CallTool request to the real tool implementation: the generic
 * registry first, then `trst_list`, then the per-workflow tools (resolved
 * fresh from the layered tool JSONs, with the JSON's `workflowRef` preset so
 * callers cannot redirect the run). Throws on malformed arguments and unknown
 * tools; the CallTool handler converts throws into `isError` tool results.
 * A run_workflow dispatch that reports `status: "failed"` throws a
 * `ToolReportError` so the structured JSON payload is surfaced as an
 * `isError` result too (a successfully started run stays plain content).
 */
async function dispatchTool(
  name: string,
  args: Record<string, unknown>,
  projectDir: string,
  homeDir: string | undefined,
  extra: CallToolExtra,
  progressIntervalMs: number | undefined,
): Promise<unknown> {
  const cwd =
    typeof args.project === "string" && args.project.trim() !== ""
      ? path.resolve(args.project)
      : projectDir;

  if (!tools.some((candidate) => candidate.name === name) && name !== TRST_LIST_TOOL.name) {
    const perWorkflowTool = findPerWorkflowTool(name, projectDir, homeDir);
    if (perWorkflowTool !== undefined) {
      return await dispatchPerWorkflowTool(perWorkflowTool, args, cwd);
    }
    throw new Error(`Unknown tool: ${name}`);
  }

  switch (name) {
    case "trst_run_workflow": {
      const workflow = readOptionalString(args.workflow) ?? readOptionalString(args.workflowRef);
      if (workflow === undefined) {
        throw new Error("`workflow` must be a non-empty string.");
      }
      const result = await runWorkflowTool({
        workflowRef: workflow,
        ...(args.input === undefined ? {} : { input: args.input }),
        cwd,
      });
      const payload = { ...result, workflow };
      if (result.status === "failed") {
        throw new ToolReportError(payload);
      }
      return payload;
    }
    case "trst_watch": {
      const runId = readOptionalString(args.runId);
      if (runId === undefined) {
        throw new Error("trst_watch: `runId` must be a non-empty string.");
      }
      // Capability detection: only a request that actually carried a
      // progress token may use the 300 s ceiling and receive keep-alives. A
      // token-less request stays exactly on the 25 s progressless ceiling.
      const progressToken = readProgressToken(extra._meta);
      const onProgress =
        progressToken === undefined ? undefined : createProgressEmitter(extra, progressToken);
      return await trst_watch(
        {
          runId,
          ...(typeof args.cursor === "number" ? { cursor: args.cursor } : {}),
          ...(args.verbosity === "brief" || args.verbosity === "normal" || args.verbosity === "full"
            ? { verbosity: args.verbosity }
            : {}),
          ...(typeof args.maxWaitMs === "number" ? { maxWaitMs: args.maxWaitMs } : {}),
          ...(args.waitFor === "attention" || args.waitFor === "terminal"
            ? { waitFor: args.waitFor }
            : {}),
        },
        {
          cwd,
          signal: extra.signal,
          ...(onProgress === undefined ? {} : { progressCapable: true, onProgress }),
          ...(progressIntervalMs === undefined ? {} : { progressIntervalMs }),
        },
      );
    }
    case "trst_answer": {
      const runId = readOptionalString(args.runId);
      const waitId = readOptionalString(args.waitId);
      if (runId === undefined || waitId === undefined) {
        throw new Error("`runId` and `waitId` must be non-empty strings.");
      }
      if (typeof args.answer !== "object" || args.answer === null || Array.isArray(args.answer)) {
        throw new Error("`answer` must be a JSON object.");
      }
      const result = await trstAnswer({
        runId,
        waitId,
        answer: args.answer as Record<string, unknown>,
        ...(readOptionalString(args.branchId) === undefined
          ? {}
          : { branchId: readOptionalString(args.branchId) }),
        ...(args.continueAfterAnswer === true ? { continueAfterAnswer: true } : {}),
        cwd,
      });
      const continueFailed = result.continued !== undefined && result.continued.resumed === false;
      if (result.persisted === false || result.error !== undefined || continueFailed) {
        // The answer never persisted (or failed outright), or it persisted but
        // the continue did not start: surface the failure as an isError tool
        // result instead of plain content, consistent with the run_workflow
        // status:"failed" convention. A persisted answer whose continue failed
        // is NOT success — reporting success makes the calling agent watch a run
        // that will never progress.
        throw new ToolReportError(result);
      }
      return result;
    }
    case "trst_resume": {
      const runId = readOptionalString(args.runId);
      if (runId === undefined) {
        throw new Error("`runId` must be a non-empty string.");
      }
      const result = await trstResume({ runId, cwd });
      // A backgrounded continue is success: trst_resume no longer waits for the
      // run to finish. Follow it with trst_watch; a run that is no longer making
      // progress reports `crashed`.
      if (result.resumed === false || result.error !== undefined) {
        // The continue did not run or failed: surface the failure as an isError
        // tool result instead of plain content, consistent with the run_workflow
        // status:"failed" convention.
        throw new ToolReportError(result);
      }
      return result;
    }
    case "trst_list": {
      return await trstList({
        projectDir: cwd,
        ...(homeDir === undefined ? {} : { homeDir }),
      });
    }
    default:
      throw new Error(`Unknown tool: ${name}`);
  }
}

/** Resolves one per-workflow tool definition by name from a fresh tool JSON load. */
function findPerWorkflowTool(
  name: string,
  projectDir: string,
  homeDir: string | undefined,
): PerWorkflowToolDefinition | undefined {
  const options = {
    projectDir,
    ...(homeDir === undefined ? {} : { homeDir }),
  };
  return loadPerWorkflowTools(options).find(
    (tool) => tool.name === name && !RESERVED_TOOL_NAMES.has(tool.name),
  );
}

/**
 * Dispatches a per-workflow tool to `runWorkflowTool` with the JSON's
 * `workflowRef` preset; the call's arguments are the workflow input.
 */
async function dispatchPerWorkflowTool(
  tool: PerWorkflowToolDefinition,
  args: Record<string, unknown>,
  cwd: string,
): Promise<unknown> {
  const result = await runWorkflowTool({
    workflowRef: tool.workflowRef,
    input: args,
    cwd,
  });
  const payload = { ...result, workflow: tool.workflowRef, tool: tool.name };
  if (result.status === "failed") {
    throw new ToolReportError(payload);
  }
  return payload;
}

function readOptionalString(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() !== "" ? value.trim() : undefined;
}

function readProgressToken(meta: CallToolExtra["_meta"]): string | number | undefined {
  const token = meta?.progressToken;
  return typeof token === "string" || typeof token === "number" ? token : undefined;
}

/**
 * Build the per-call progress emitter. It sends one `notifications/progress`
 * per `onProgress` call (the watch owns the 10 s cadence), uses elapsed seconds
 * as a monotonically non-decreasing progress value, and reports the effective
 * budget as the total. Notification delivery is best-effort: a rejection or
 * throw disables further emission for this call and never changes the watch
 * result.
 */
function createProgressEmitter(
  extra: CallToolExtra,
  progressToken: string | number,
): (progress: TrstWatchProgressEvent) => void {
  const startedAt = Date.now();
  let lastProgressSeconds = 0;
  let disabled = false;

  return (progress) => {
    if (disabled || extra.signal.aborted) {
      return;
    }
    const elapsedSeconds = Math.max(lastProgressSeconds, (Date.now() - startedAt) / 1000);
    lastProgressSeconds = elapsedSeconds;
    const total = Math.max(0, Math.round(progress.effectiveWaitMs / 1000));
    try {
      void extra
        .sendNotification({
          method: "notifications/progress",
          params: {
            progressToken,
            progress: elapsedSeconds,
            total,
            message: progressMessage(progress),
          },
        })
        .catch(() => {
          disabled = true;
        });
    } catch {
      disabled = true;
    }
  };
}

/** One short line, never raw event text (a step id may still contain whitespace). */
function progressMessage(progress: TrstWatchProgressEvent): string {
  const step = progress.step === undefined ? undefined : collapseToOneLine(progress.step);
  return step === undefined ? `state=${progress.state}` : `state=${progress.state} step=${step}`;
}

function collapseToOneLine(value: string): string | undefined {
  // Fold whitespace and every C0/C1 control character (U+0000-U+001F,
  // U+007F-U+009F, including NEL) into one dash so a step id can never inject
  // a control sequence or a second line into a progress notification.
  const collapsed = value.replace(/[\s\p{Cc}]+/gu, "-").trim();
  if (collapsed === "") {
    return undefined;
  }
  return collapsed.length > 80 ? `${collapsed.slice(0, 77)}...` : collapsed;
}

/**
 * Instructions resource content: the project's `.trailstep/mcp/instructions.md`
 * when present, else the embedded generic + static snippet.
 */
function readInstructions(projectDir: string): string {
  const projectInstructions = path.join(projectDir, ".trailstep", "mcp", "instructions.md");
  if (existsSync(projectInstructions)) {
    try {
      return readFileSync(projectInstructions, "utf8");
    } catch {
      // Fall through to the embedded snippet on any read failure.
    }
  }
  return INSTRUCTIONS_FALLBACK;
}
